/* Phase 330: dedicated transparent 4K images for Snowa TV and oven records. */
add_action('init',function(){
 if(get_option('bhc_catalog_image_snowa_tv_oven_remediation_v330'))return;
 @ini_set('memory_limit','768M');$base=__DIR__.'/';$upload=wp_upload_dir();$map=[959=>['model'=>'ssd-55lsq700u','file'=>'snowa-ssd-55lsq700u-v330-source.png'],1005=>['model'=>'ssd-50ls500u','file'=>'snowa-ssd-50ls500u-v330-source.png'],1006=>['model'=>'ssd-43sk14300m','file'=>'snowa-ssd-43sk14300m-v330-source.png'],962=>['model'=>'seo7-8323','file'=>'snowa-seo7-8323-v330-source.png']];
 foreach($map as $id=>$it){$src=$base.$it['file'];if(!is_readable($src))continue;$old=get_post_thumbnail_id($id);if($old)wp_delete_attachment($old,true);$im=@imagecreatefrompng($src);if(!$im)continue;$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=(int)round($w*$scale);$nh=(int)round($h*$scale);$out=imagecreatetruecolor($nw,$nh);imagealphablending($out,false);imagesavealpha($out,true);$c=imagecolorallocatealpha($out,0,0,0,127);imagefilledrectangle($out,0,0,$nw,$nh,$c);imagecopyresampled($out,$im,0,0,0,0,$nw,$nh,$w,$h);$rel='bhc-image-references/snowa-'.$it['model'].'-v330.png';$dst=trailingslashit($upload['basedir']).$rel;wp_mkdir_p(dirname($dst));@unlink($dst);imagepng($out,$dst,6);imagedestroy($out);imagedestroy($im);$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>'Snowa '.$it['model'].' transparent 4K','post_status'=>'inherit'],$dst,$id);if(!$aid)continue;update_post_meta($aid,'_wp_attached_file',$rel);update_post_meta($aid,'_wp_attachment_metadata',['width'=>$nw,'height'=>$nh,'file'=>$rel,'sizes'=>[],'image_meta'=>[]]);set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','generated_4k_transparent_verified');update_post_meta($id,'_bhc_image_prompt','Exact Snowa '.$it['model'].' product cutout, transparent background, isolated catalog view, 4K canvas, no text, no watermark.');}
